// gshare branch predictor, 128-entry PHT, 2-bit saturating counters,
// separate prediction and training interfaces.
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] global_history;
    wire [6:0] hash = global_history ^ predict_pc;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1)
                pht[i] <= 2'b10;
            global_history <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_taken <= pht[hash][1] > pht[hash][0];
                predict_history <= global_history;
                if (predict_taken)
                    global_history <= global_history + 1;
                else
                    global_history <= global_history - 1;
            end
            if (train_valid) begin
                if (train_taken != pht[hash][1] > pht[hash][0])
                    pht[hash][1] <= pht[hash][1] + 1;
                else
                    pht[hash][0] <= pht[hash][0] + 1;
                if (train_mispredicted)
                    global_history <= train_history;
                else
                    global_history <= global_history + (predict_taken ? 1 : -1);
            end
        end
    end
endmodule

