// GSHARE branch predictor, with 128-entry saturating 2-bit counter per
// history register index, hashed (XOR) to the index.
module TopModule(
    input  clk,
    input  areset,
    // Prediction interface: answer whether to predict taken
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    // Training interface: tell us the actual branch outcome and whether
    // the branch was a misprediction (causing a pipeline flush). Update
    // the pattern history table (PHT) to train the branch predictor to
    // predict this branch more accurately next time.
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] ctr [0:127];
    reg [6:0] global_history;
    always @(posedge clk) begin
        reg [1:0] ctr_next;
        reg [6:0] global_history_next;
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) ctr[i] <= 2'b10;
            global_history <= 7'd0;
        end else begin
            ctr_next = ctr[{global_history, predict_pc} ^ 7'd63];
            global_history_next = (predict_taken ? global_history + 1 : global_history - 1);
            if (predict_valid) begin
                predict_taken <= (ctr_next > 2) ? 1'b1 : 1'b0;
                predict_history <= global_history_next;
            end
            if (train_valid) begin
                ctr[{global_history, train_pc} ^ 7'd63] <= (train_taken ? ctr_next + 2'b01 : ctr_next - 2'b01);
                global_history_next = (train_mispredicted ? train_history : global_history_next);
            end
            global_history <= global_history_next;
        end
    end
endmodule

