// GSHARE ONE-LEVEL PIPELINED BRANCH PREDICTOR, IMPLEMENTED AS AN ONE-CYCLE
// PIPELINED HASHED GLOBAL BRANCH HISTORY + PATTERN HISTORY TABLE
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] ghistory;
    reg [1:0] pht_pred;
    reg predict_taken_reg;
    wire [6:0] pc_hash = predict_pc ^ ghistory;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b11;
            ghistory <= 7'd0;
        end else begin
            if (predict_valid) begin
                pht_pred <= pht[pc_hash];
                predict_taken_reg <= (pht_pred > 1);
                predict_history <= ghistory;
            end
            if (train_valid) begin
                pht[pc_hash] <= (train_mispredicted ? 2'b11 : (train_taken ? pht[pc_hash] + 1 : pht[pc_hash] - 1)) & 2'b11;
                ghistory <= train_mispredicted ? train_history : ghistory + (train_taken ? 7'd1 : 7'd-1);
            end
        end
    end
    assign predict_taken = predict_taken_reg;
endmodule

