    wire [6:0] index = global_history ^ predict_pc;

    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b00;
            global_history <= 7'b0;
            predict_taken <= 1'b0;
            predict_history <= 7'b0;
