// (single-cycle per-stage predictor, plus 2-stage per-stage predictor,
//  plus 2-stage per-stage predictor on the "younger" branch that's
//  predicted to go to the same PC as the older branch)
module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] global_history;
    reg [1:0] pht_younger [0:127];
    wire [6:0] pc_hash = predict_pc ^ global_history;
    wire [1:0] pht_pred = pht[pc_hash];
    wire [1:0] pht_younger_pred = pht_younger[pc_hash];
    reg predict_taken_reg;
    reg [6:0] predict_history_reg;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b11;
                pht_younger[i] <= 2'b11;
            end
            global_history <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_taken_reg <= (pht_pred >= 2'b11) ? 1'b1 : 1'b0;
                predict_history_reg <= global_history;
            end
            if (train_valid) begin
                pht[pc_hash] <= (train_taken ? pht[pc_hash] + 1 : pht[pc_hash] - 1) & 2'b11;
                pht_younger[pc_hash] <= (train_mispredicted ? 2'b11 : (train_taken ? pht_younger[pc_hash] + 1 : pht_younger[pc_hash] - 1)) & 2'b11;
                if (train_mispredicted) global_history <= train_history;
                else global_history <= global_history + 1;
            end
        end
    end
    assign predict_taken = predict_taken_reg;
    assign predict_history = predict_history_reg;
endmodule

