samples.raw_completion:
// GSHARE branch predictor, one-bit saturating counters, 7-bit history,
// separate predict and train interfaces.
module TopModule(
  input  clk,
  input  areset,
  input  predict_valid,
  input  [6:0] predict_pc,
  output reg predict_taken,
  output reg [6:0] predict_history,
  input  train_valid,
  input  train_taken,
  input  train_mispredicted,
  input  [6:0] train_history,
  input  [6:0] train_pc
);
  reg [1:0] pht [0:127];
  reg [6:0] history;
  reg [6:0] pc_hash;
  reg [1:0] predict_counter;
  wire predict_taken_reg;
  reg [6:0] predict_history_reg;
  always @(posedge clk) begin
    if (areset) begin
      for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b00;
      history <= 7'd0;
    end else begin
      if (train_valid) begin
        pht[pc_hash][train_taken] <= pht[pc_hash][train_taken] + 2'b01;
        if (train_mispredicted) history <= train_history;
      end else if (predict_valid) begin
        predict_counter = pht[pc_hash][predict_taken_reg];
        predict_history_reg <= history;
        history <= (history + 7'd1) ^ predict_pc[6:0];
      end
    end
  end
  always @(*) begin
    pc_hash = (history ^ predict_pc) & 7'd63;
    predict_taken_reg = pht[pc_hash][1];
  end
  assign predict_taken = predict_taken_reg;
  always @(posedge clk) begin
    if (areset) predict_history <= 7'd0;
    else if (predict_valid) predict_history <= predict_history_reg;
  end
endmodule

