samples.raw_completion:
// GSHARE 1-CYCLE PIPELINED BRANCH PREDICTOR: A 7-BIT PC, 7-BIT GLOBAL
// HISTORY, HASHED INTO A 7-BIT INDEX, ACCESSING A 128-ENTRY TABLE OF
// TWO-BIT SATURATING COUNTERS.
module TopModule(
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] global_history;
    reg [1:0] counter;
    reg [6:0] pc_hashed;
    reg [1:0] prediction;
    reg [1:0] saturated_counter;
    reg [1:0] new_counter;
    reg [6:0] new_history;

    always @(*) begin
        pc_hashed = global_history ^ predict_pc;
        counter = pht[pc_hashed];
        if (counter > 1) saturation = 1;
        if (counter < 0) saturation = 0;
        saturated_counter = counter;
        if (predict_taken) saturated_counter = counter + 1;
        if (!predict_taken) saturated_counter = counter - 1;
        if (saturated_counter > 1) prediction = 1;
        if (saturated_counter < 0) prediction = 0;
        if (saturated_counter == 1) prediction = predict_taken;
        if (saturated_counter == 0) prediction = !predict_taken;
    end

    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'b0;
            global_history <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_taken <= prediction;
                predict_history <= global_history;
                global_history <= (global_history << 1) | predict_taken;
                global_history <= global_history & 7'h7F;
            end
            if (train_valid) begin
                new_counter = pht[pc_hashed];
                if (train_taken) new_counter = new_counter + 1;
                if (!train_taken) new_counter = new_counter - 1;
                pht[pc_hashed] <= new_counter;
                if (train_mispredicted) global_history <= train_history;
                else global_history <= (global_history << 1) | train_taken;
                global_history <= global_history & 7'h7F;
            end
        end
    end
endmodule

